import openpyxl
a=openpyxl.load_workbook('mimotable_batch1_0401_template_1194_input.xlsx')
b=openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_mimotable_batch1/passed/template/mimotable_batch1_0401_template_1194_golden.xlsx')
wa=a['Sheet1']; wb=b['Sheet1']
# Compare key style properties for all cells in data region
props=['number_format','font','fill','border','alignment','protection']
diff=[]
for r in range(1,27):
    for c in range(1,13):
        ca=wa.cell(row=r,column=c); cb=wb.cell(row=r,column=c)
        for p in props:
            va=getattr(ca,p); vb=getattr(cb,p)
            # compare salient fields
            if p=='number_format':
                if va!=vb: diff.append((ca.coordinate,p,va,vb))
            elif p=='font':
                fa=(va.name, va.sz, va.bold, va.italic, va.color.rgb if va.color else None)
                fb=(vb.name, vb.sz, vb.bold, vb.italic, vb.color.rgb if vb.color else None)
                if fa!=fb: diff.append((ca.coordinate,p,fa,fb))
            elif p=='fill':
                fa=(va.fgColor.rgb if va.fgColor else None, va.patternType)
                fb=(vb.fgColor.rgb if vb.fgColor else None, vb.patternType)
                if fa!=fb: diff.append((ca.coordinate,p,fa,fb))
            elif p=='border':
                fa=(va.left.style, va.right.style, va.top.style, va.bottom.style)
                fb=(vb.left.style, vb.right.style, vb.top.style, vb.bottom.style)
                if fa!=fb: diff.append((ca.coordinate,p,fa,fb))
print('style diff count', len(diff))
for d in diff[:30]: print(d)
print('merged a', wa.merged_cells.ranges)
print('merged b', wb.merged_cells.ranges)
